<script>
  // The logo is the mark and the word: a page of the document with the komodo's
  // scales down its edge, then "Komo" in the site's green and "Doc" in ink. The
  // three parts are separate paths, so each takes its colour from the theme
  // rather than from the file, and the ink half stays legible on a dark surface.
  //
  // Two sizes: the one on the bar, and the one above a page that introduces
  // itself. A caller asks for a size rather than reaching in with a selector,
  // which is what lets these styles stay scoped to this file.
  let { size = "bar" } = $props();
</script>

